import web
from web import HTTPException

def deny_access(url):
    try:
        web.request.url_exceptions.HTTP_403 = {"reason": "Access Denied"}
        return 403
    except web.HTTPException as e:
        return e

if __name__ == "__main__":
    url = "example.com"
    try:
        web.request.url_exceptions.HTTP_403 = {"reason": "Access Denied"}
        return deny_access(url)
    except web.HTTPException as e:
        print(f"Status: {e.status_code}")
        return {"error": f"Error {e.status_code}: {e.reason}"}
```

