import requests
import sys

def deny_access(password):
    # Check your firewall rules first (adjust for your setup)
    headers = {"User-Agent": "deny_access_check.py"}
    url = "http://example.com"
    try:
        r = requests.get(url, headers=headers, timeout=5)
        print(f"Access denied by firewall rule {password}")
    except Exception as e:
        print(f"Failed to reach {url} because of {e}")

if __name__ == "__main__":
    try:
        # Set your password here for your firewall rule
        deny_access("your_password")
    except Exception as e:
        print(f"ERROR: {e}")
```

